private void queueGunWave(Enemy e, Point2D.Double current, double power, double speed,
        double bearing, int seg, double[] angles, double[] input, boolean virtual) {
    if (outgoing.size() >= 96) return;
    GunWave w = new GunWave();
    w.owner = e; w.x = getX(); w.y = getY();
    w.time = getTime(); w.speed = speed; w.power = power;
    w.bearing = bearing; w.direction = e.direction;
    w.segment = seg; w.angles = angles; w.features = input; w.virtual = virtual;
    w.previousX = current.x; w.previousY = current.y; w.previousTime = getTime();
    outgoing.add(w);
}

